require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('campaigns.manage');
if(is_post()){verify_csrf();try{$spot=strtoupper(trim((string)input('spot_id')));$spot=preg_replace('/[^A-Z0-9_-]/','_',$spot);$name=trim((string)input('spot_name'));$lat=(float)input('latitude');$lon=(float)input('longitude');$proximity=(int)input('proximity_alert_radius',30);$unlock=(int)input('scanner_unlock_radius',20);$reward=trim((string)input('reward_amount'));if(!preg_match('/^[A-Z0-9_-]{3,64}$/',$spot)||$name===''||$lat<-90||$lat>90||$lon<-180||$lon>180||$proximity<1||$unlock<1||$unlock>$proximity||!preg_match('/^\d{1,16}(\.\d{1,2})?$/',$reward))throw new InvalidArgumentException('Check spot ID, coordinates, distances, and reward.');$wl=array_values(array_filter(array_map('trim',explode(',',(string)input('whitelisted_users')))));$token=bin2hex(random_bytes(32));$pdo=db();$pdo->beginTransaction();$pdo->prepare('INSERT INTO spot_campaigns(spot_id,master_token_hash,spot_name,category_id,target_scope,whitelisted_users,city_zone,venue_name,latitude,longitude,proximity_alert_radius,scanner_unlock_radius,indoor_micro_clue,reward_type,reward_amount,min_cart_value,ttl_minutes,auto_reversal,max_budget_scans,scan_frequency_policy,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$spot,hash('sha256',$token),$name,(int)input('category_id')?:null,strtoupper((string)input('target_scope')),$wl?safe_json($wl):safe_json([]),trim((string)input('city_zone')),trim((string)input('venue_name')),$lat,$lon,$proximity,$unlock,trim((string)input('indoor_micro_clue')),strtoupper((string)input('reward_type')),$reward,trim((string)input('min_cart_value')),max(1,(int)input('ttl_minutes',30)),filter_var(input('auto_reversal'),FILTER_VALIDATE_BOOL)?1:0,max(1,(int)input('max_budget_scans',500)),strtoupper((string)input('scan_frequency_policy')),(int)admin()['id']]);$riddle=trim((string)input('riddle_text'));if($riddle!==''){$syn=array_values(array_filter(array_map('trim',explode(',',(string)input('synonyms')))));$pdo->prepare('INSERT INTO riddle_pool(spot_id,riddle_text,primary_answer,synonyms,yt_video_id,weight_percentage) VALUES(?,?,?,?,?,?)')->execute([$spot,$riddle,trim((string)input('primary_answer')),safe_json($syn),trim((string)input('yt_video_id'))?:null,max(1,min(100,(int)input('weight_percentage',100)))]);}audit_log((int)admin()['id'],'MASTER_SPOT_CREATED','spot_campaigns',$spot,null,['token_issued'=>true]);$pdo->commit();$_SESSION['_master_qr_once']='hunter://spot?t='.$token;flash('success','Master campaign saved. Copy the one-time QR payload shown below.');}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}redirect('/admin/campaigns/index.php');}
